		return n == expected, nil
	case opNEQ:
		return n != expected, nil
	case opLT:
		return n < expected, nil
	case opLTE:
		return n <= expected, nil
	case opGT:
		return n > expected, nil
	case opGTE:
		return n >= expected, nil
	}
	return false, nil
}

