func TestConstraintComparisons(t *testing.T) {
	t.Run("string operators trim whitespace and ignore operator case", func(t *testing.T) {
		constraint := constraint{
			Type: flipt.ComparisonType_STRING_COMPARISON_TYPE, Property: "name", Operator: "PREFIX", Value: "  ab  ",
		}
		match, err := matchesConstraint(constraint, " abc ", true)
		require.NoError(t, err)
		assert.True(t, match)
	})

	t.Run("decimal and boolean inputs are validated", func(t *testing.T) {
		_, err := matchesNumber(constraint{Operator: opGT, Value: "1"}, "not-a-number")
		require.Error(t, err)
		_, err = matchesBool(constraint{Operator: opTrue}, "yes")
		require.Error(t, err)
	})

	t.Run("operators without constraint values are accepted", func(t *testing.T) {
		cases := []constraint{
			{Type: flipt.ComparisonType_STRING_COMPARISON_TYPE, Property: "x", Operator: opEmpty},
			{Type: flipt.ComparisonType_STRING_COMPARISON_TYPE, Property: "x", Operator: opNotEmpty},
			{Type: flipt.ComparisonType_NUMBER_COMPARISON_TYPE, Property: "x", Operator: opPresent},
			{Type: flipt.ComparisonType_NUMBER_COMPARISON_TYPE, Property: "x", Operator: opNotPresent},
			{Type: flipt.ComparisonType_BOOLEAN_COMPARISON_TYPE, Property: "x", Operator: opTrue},
			{Type: flipt.ComparisonType_BOOLEAN_COMPARISON_TYPE, Property: "x", Operator: opFalse},
		}
		for _, constraint := range cases {
			require.NoError(t, validate(constraint), constraint.Operator)
		}
	})
}

func TestConsistentHashAndInclusiveCutoff(t *testing.T) {
	const entityID = "customer-1"
	const flagKey = "checkout"
	bucket := uint(crc32.ChecksumIEEE([]byte(flagKey+entityID))) % totalBucketNum
	assert.Equal(t, bucket, crc32Num(entityID, flagKey))

	request := &flipt.EvaluationRequest{EntityId: entityID, FlagKey: flagKey}
	distributions := []distribution{{VariantKey: "first"}, {VariantKey: "second"}}
	matched, selected := evaluate(request, distributions, []int{int(bucket), int(totalBucketNum)})
	require.True(t, matched)
	assert.Equal(t, "first", selected.VariantKey)
}

func TestEvaluatorStorageUsesRuleRank(t *testing.T) {
	flag, err := flagStore.CreateFlag(context.Background(), &flipt.CreateFlagRequest{
		Key: t.Name(), Name: t.Name(), Enabled: true,
	})
	require.NoError(t, err)

	segments := []string{t.Name() + "-rank-2", t.Name() + "-rank-1"}
	for i, key := range segments {
		_, err := segmentStore.CreateSegment(context.Background(), &flipt.CreateSegmentRequest{Key: key, Name: key})
		require.NoError(t, err)
		rank := int32(2 - i)
		_, err = ruleStore.CreateRule(context.Background(), &flipt.CreateRuleRequest{
			FlagKey: flag.Key, SegmentKey: key, Rank: rank,
		})
		require.NoError(t, err)
	}

	response, err := evaluatorStore.Evaluate(context.Background(), &flipt.EvaluationRequest{
		FlagKey: flag.Key, EntityId: "customer-1",
	})
	require.NoError(t, err)
	assert.True(t, response.Match)
	assert.Equal(t, segments[1], response.SegmentKey)
}

func TestEvaluatorStorageZeroPercentDistribution(t *testing.T) {
