 74	// Evaluate evaluates a request for a flag and entity.
 75	func (s *EvaluatorStorage) Evaluate(ctx context.Context, r *flipt.EvaluationRequest) (*flipt.EvaluationResponse, error) {
 76		if r == nil {
 77			return nil, ErrInvalidf("evaluation request must not be nil")
 78		}
 79	
 80		requestID := r.RequestId
 81		if requestID == "" {
 82			requestID = uuid.Must(uuid.NewV4()).String()
 83		}
 84	
 85		timestamp, err := ptypes.TimestampProto(time.Now().UTC())
 86		if err != nil {
 87			return nil, err
 88		}
 89	
 90		resp := &flipt.EvaluationResponse{
 91			RequestId:      requestID,
 92			EntityId:       r.EntityId,
 93			RequestContext: r.Context,
 94			Timestamp:      timestamp,
 95			FlagKey:        r.FlagKey,
 96		}
 97		logger := s.logger.WithField("request", r)
 98		logger.Debug("evaluate")
 99	
100		var enabled bool
101		err = s.builder.Select("enabled").
102			From("flags").
103			Where(sq.Eq{"key": r.FlagKey}).
104			QueryRowContext(ctx).
105			Scan(&enabled)
106		if err != nil {
107			if errors.Is(err, sql.ErrNoRows) {
108				return resp, ErrNotFoundf("flag %q", r.FlagKey)
109			}
110			return resp, err
111		}
112		if !enabled {
113			return resp, ErrInvalidf("flag %q is disabled", r.FlagKey)
114		}
115	
116		rules, err := s.rules(ctx, r.FlagKey)
117		if err != nil {
118			return resp, err
119		}
120	
121		for _, rule := range rules {
122			matched := true
123			for _, c := range rule.Constraints {
124				value, present := r.Context[c.Property]
125				ok, err := matchesConstraint(c, value, present)
126				if err != nil {
127					return resp, err
128				}
129				if !ok {
130					matched = false
131					break
132				}
133			}
134			if !matched {
135				continue
136			}
137	
138			resp.SegmentKey = rule.SegmentKey
139			distributions, cutoffs, err := s.distributions(ctx, rule.ID)
140			if err != nil {
141				return resp, err
142			}
143			if len(distributions) == 0 {
144				resp.Match = true
145				return resp, nil
146			}
147	
148			if ok, selected := evaluate(r, distributions, cutoffs); ok {
149				resp.Match = true
150				resp.Value = selected.VariantKey
151			}
152			return resp, nil
153		}
154	
155		return resp, nil
156	}
